/**
 * DRAG-15. Pressure drag coefficient C₃(M) of nose cones of fineness ratio 3,
 * referred to the base area, transcribed from NASA TR R-100 (Stoney 1961)
 * Figure 12, printed page 16 (PDF page 20), as Niskanen Appendix B.3 p. 108
 * prescribes ("these curves are written into the software as data curve
 * points"). Owner's approval and the digitisation rules: D-053; the
 * digitisation, its uncertainty and the panel (b) identity correction: D-055.
 *
 * Every value is the mean of two independent digitisation passes recorded in
 * `reference/digitised/tr-r-100-figure-12.json` (generated by
 * `merge-tr-r-100.py` from the two pass files); `uncertainty` is the larger of
 * half the worst disagreement between the passes and the reading floor 0.005.
 * A test in the formats package checks these arrays against that file.
 *
 * Panel (a) (Mach 0.8 to 2.0, free-flight data of the report with wind tunnel
 * points of its ref. 30) is used for every nose it shows; panel (b) (Mach 0.8
 * to 3.6, ref. 30 wind tunnel data) supplies the x^1/4 and ellipsoidal noses,
 * whose data begin at Mach 1.2. Between the points the model interpolates
 * linearly in Mach; beyond the last point it holds the last value (DRAG-15).
 */

export interface StoneyCurve {
  /** Configuration number in TR R-100 Table I, or the reference for panel (b) data. */
  readonly configuration: string;
  readonly panel: 'a' | 'b';
  /** Reading uncertainty in C_D,N (D-055). */
  readonly uncertainty: number;
  /** [Mach, C_D,N] in increasing Mach. */
  readonly points: readonly (readonly [number, number])[];
}

export type StoneyNose =
  | 'cone'
  | 'power-1/4'
  | 'power-1/2'
  | 'power-3/4'
  | 'parabola-1/2'
  | 'parabola-3/4'
  | 'parabola'
  | 'von-karman'
  | 'lv-haack'
  | 'ellipsoid';

